import (
	"fmt"
	"math/big"
)

type Rational struct{ value *big.Rat }

func rational(n int64) Rational            { return Rational{big.NewRat(n, 1)} }
func ratio(n, d int64) Rational            { return Rational{big.NewRat(n, d)} }
func (a Rational) Add(b Rational) Rational { return Rational{new(big.Rat).Add(a.value, b.value)} }
func (a Rational) Sub(b Rational) Rational { return Rational{new(big.Rat).Sub(a.value, b.value)} }
func (a Rational) Mul(b Rational) Rational { return Rational{new(big.Rat).Mul(a.value, b.value)} }
func (a Rational) Div(b Rational) Rational { return Rational{new(big.Rat).Quo(a.value, b.value)} }
func (a Rational) Cmp(b Rational) int      { return a.value.Cmp(b.value) }
func (a Rational) Sign() int               { return a.value.Sign() }
func (a Rational) String() string          { return a.value.RatString() }
func (a Rational) Real() float64 {
	n, _ := new(big.Float).SetInt(a.value.Num()).Float64()
	d, _ := new(big.Float).SetInt(a.value.Denom()).Float64()
	return n / d
}
func (a Rational) Round() int64 {
	n := new(big.Int).Mul(a.value.Num(), big.NewInt(2))
	n.Add(n, a.value.Denom())
	d := new(big.Int).Mul(a.value.Denom(), big.NewInt(2))
	q, r := new(big.Int), new(big.Int)
	q.QuoRem(n, d, r)
	if n.Sign() < 0 && r.Sign() != 0 {
		q.Sub(q, big.NewInt(1))
	}
	return q.Int64()
}

type Point struct{ X, Y Rational }

func point(x, y int64) Point       { return Point{rational(x), rational(y)} }
func (p Point) Equal(q Point) bool { return p.X.Cmp(q.X) == 0 && p.Y.Cmp(q.Y) == 0 }
func (p Point) String() string     { return fmt.Sprintf("(%s,%s)", p.X, p.Y) }
func pointLess(p, q Point) bool {
	c := p.Y.Cmp(q.Y)
	if c != 0 {
		return c < 0
	}
	return p.X.Cmp(q.X) < 0
}
func cross(o, a, b Point) Rational {
	return a.X.Sub(o.X).Mul(b.Y.Sub(o.Y)).Sub(a.Y.Sub(o.Y).Mul(b.X.Sub(o.X)))
}
func along(a, b Point, t Rational) Point {
	return Point{a.X.Add(t.Mul(b.X.Sub(a.X))), a.Y.Add(t.Mul(b.Y.Sub(a.Y)))}
}
func segmentText(a, b Point) string { return a.String() + "-" + b.String() }

package main

type Rendered struct {
	Rows               []string
	Result, A, B, Both int
}

func render(result *Result, x0, y0, cw, ch, cols, rows int64) Rendered {
	out := Rendered{}
	rings := flatten(result.Polygons)
	for j := int64(0); j < rows; j++ {
		row := make([]byte, cols)
		for i := int64(0); i < cols; i++ {
			p := Point{rational(x0).Add(ratio((2*i+1)*cw, 2)), rational(y0).Add(ratio((2*(rows-1-j)+1)*ch, 2))}
			character := byte('.')
			if interior(p, rings) {
				character = '#'
				out.Result++
			} else if result.A != nil && result.B != nil {
				a, b := interior(p, result.A.Rings), interior(p, result.B.Rings)
				if a && b {
					character = '+'
					out.Both++
				} else if a {
					character = 'a'
					out.A++
				} else if b {
					character = 'b'
					out.B++
				}
			}
			row[i] = character
		}
		out.Rows = append(out.Rows, string(row))
	}
	return out
}

package main

import (
	"math"
	"slices"
	"sort"
)

type Ring []Point

func insideRing(p Point, ring Ring) bool {
	inside := false
	for i, u := range ring {
		w := ring[(i+1)%len(ring)]
		if (u.Y.Cmp(p.Y) > 0) == (w.Y.Cmp(p.Y) > 0) {
			continue
		}
		lo, hi := u, w
		if lo.Y.Cmp(hi.Y) > 0 {
			lo, hi = hi, lo
		}
		if cross(lo, hi, p).Sign() > 0 {
			inside = !inside
		}
	}
	return inside
}
func interior(p Point, rings []Ring) bool {
	inside := false
	for _, ring := range rings {
		if insideRing(p, ring) {
			inside = !inside
		}
	}
	return inside
}
func boundary(p Point, ring Ring) bool {
	for i, a := range ring {
		if onSegment(p, a, ring[(i+1)%len(ring)]) {
			return true
		}
	}
	return false
}
func rotate(ring Ring) Ring {
	first := 0
	for i, p := range ring {
		if pointLess(p, ring[first]) {
			first = i
		}
	}
	out := append(slices.Clone(ring[first:]), ring[:first]...)
	return out
}
func ccw(ring Ring) bool { return cross(ring[len(ring)-1], ring[0], ring[1]).Sign() > 0 }
func reverse(ring Ring) Ring {
	out := make(Ring, len(ring))
	out[0] = ring[0]
	for i := 1; i < len(ring); i++ {
		out[i] = ring[len(ring)-i]
	}
	return out
}
func normalize(ring Ring, outer bool) Ring {
	out := rotate(ring)
	if ccw(out) != outer {
		out = reverse(out)
	}
	return out
}
func canonical(input []Ring) *Polygon {
	p := &Polygon{Input: make([]Ring, len(input)), Rings: make([]Ring, len(input))}
	for i, ring := range input {
		p.Input[i] = slices.Clone(ring)
		p.Rings[i] = normalize(ring, i == 0)
	}
	sort.Slice(p.Rings[1:], func(i, j int) bool { return pointLess(p.Rings[i+1][0], p.Rings[j+1][0]) })
	return p
}
func assemble(input []Ring) []*Polygon {
	rings := make([]Ring, len(input))
	depth := make([]int, len(input))
	for i, r := range input {
		rings[i] = rotate(r)
	}
	for i, r := range rings {
		for j, other := range rings {
			if i != j && insideRing(r[0], other) {
				depth[i]++
			}
		}
		if ccw(r) != (depth[i]%2 == 0) {
			rings[i] = reverse(r)
		}
	}
	outer := []int{}
	for i := range rings {
		if depth[i]%2 == 0 {
			outer = append(outer, i)
		}
	}
	sort.Slice(outer, func(i, j int) bool { return pointLess(rings[outer[i]][0], rings[outer[j]][0]) })
	out := []*Polygon{}
	for _, i := range outer {
		holes := []Ring{}
		for j, r := range rings {
			if depth[j] == depth[i]+1 && insideRing(r[0], rings[i]) {
				holes = append(holes, r)
			}
		}
		sort.Slice(holes, func(i, j int) bool { return pointLess(holes[i][0], holes[j][0]) })
		out = append(out, &Polygon{Rings: append([]Ring{rings[i]}, holes...)})
	}
	return out
}
func ringArea(ring Ring) float64 {
	sum := 0.0
	for i, p := range ring {
		q := ring[(i+1)%len(ring)]
		sum += p.X.Real()*q.Y.Real() - q.X.Real()*p.Y.Real()
	}
	return sum / 2
}
func ringPerimeter(ring Ring) float64 {
	sum := 0.0
	for i, p := range ring {
		q := ring[(i+1)%len(ring)]
		dx, dy := q.X.Real()-p.X.Real(), q.Y.Real()-p.Y.Real()
		sum += math.Sqrt(dx*dx + dy*dy)
	}
	return sum
}
func flatten(polygons []*Polygon) []Ring {
	out := []Ring{}
	for _, p := range polygons {
		out = append(out, p.Rings...)
	}
	return out
}
func totalArea(polygons []*Polygon) float64 {
	sum := 0.0
	for _, ring := range flatten(polygons) {
		sum += ringArea(ring)
	}
	return sum
}
